// Publish an event to NATS; the producer does not wait for consumers.
nc, _ := nats.Connect(nats.DefaultURL)
defer nc.Drain()

evt := OrderPlaced{ID: "o-42", Total: 1999}
data, _ := json.Marshal(evt)
if err := nc.Publish("orders.placed", data); err != nil { // fire-and-forget
	log.Fatal(err)
}

// A consumer in another service subscribes and reacts on its own schedule.
_, _ = nc.Subscribe("orders.placed", func(m *nats.Msg) {
	var e OrderPlaced
	_ = json.Unmarshal(m.Data, &e)
	fmt.Printf("reserving inventory for %s\n", e.ID)
})

// Pub/sub: one publish fans out to every subscriber of the subject.
nc, _ := nats.Connect(nats.DefaultURL)

// Subscriber A: send a welcome email.
_, _ = nc.Subscribe("users.created", func(m *nats.Msg) {
	fmt.Printf("emailer: welcome %s\n", string(m.Data))
})
// Subscriber B: added later, producer unchanged.
_, _ = nc.Subscribe("users.created", func(m *nats.Msg) {
	fmt.Printf("analytics: track signup %s\n", string(m.Data))
})

_ = nc.Publish("users.created", []byte("alice")) // both A and B receive it

// Orchestration: one coordinator drives each step and compensates on failure.
func (o *Orchestrator) PlaceOrder(ctx context.Context, ord Order) error {
	if err := o.inventory.Reserve(ctx, ord.Items); err != nil {
		return fmt.Errorf("reserve: %w", err)
	}
	if err := o.payment.Charge(ctx, ord.Total); err != nil {
		_ = o.inventory.Release(ctx, ord.Items) // compensating action
		return fmt.Errorf("charge: %w", err)
	}
	return o.shipping.Schedule(ctx, ord.ID)
}

// Choreography alternative: no coordinator — each service subscribes to the
// previous step's event and publishes the next, e.g. inventory listens for
// "orders.placed" and publishes "inventory.reserved" on its own.

// A -> B -> C sync chain WITHOUT bounds: D's slowness pins everyone.
func (a *A) Handle(ctx context.Context) error {
	// No per-call deadline: this blocks as long as B (and thus C, D) takes.
	return a.b.Do(ctx) // if D hangs, this goroutine hangs, pool drains, A dies
}

// Bounded version: give each hop its own deadline so failure is contained.
func (a *A) HandleSafe(ctx context.Context) error {
	ctx, cancel := context.WithTimeout(ctx, 150*time.Millisecond)
	defer cancel()
	return a.b.Do(ctx) // fails fast on slowness instead of piling up

