package main

import (
	"context"
	"fmt"
	"time"

	"google.golang.org/grpc"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/credentials/insecure"
	"google.golang.org/grpc/status"

	orderpb "example.com/order/proto"
)

func getOrder(id string) (*orderpb.Order, error) {
	// Bound the whole call to 200ms; cancel releases resources.
	ctx, cancel := context.WithTimeout(context.Background(), 200*time.Millisecond)
	defer cancel()

	conn, err := grpc.NewClient("orders:50051",
		grpc.WithTransportCredentials(insecure.NewCredentials()))
	if err != nil {
		return nil, err
	}
	defer conn.Close()

	client := orderpb.NewOrderServiceClient(conn)
	resp, err := client.GetOrder(ctx, &orderpb.GetOrderRequest{Id: id}) // blocks until reply or deadline
	if err != nil {
		if status.Code(err) == codes.DeadlineExceeded {
			return nil, fmt.Errorf("order service too slow: %w", err)
		}
		return nil, err
	}
	return resp, nil
}

func main() {
	o, err := getOrder("o-42")
	if err != nil {
		fmt.Println("error:", err)
		return
	}
	fmt.Println("status:", o.Status)
}

package main

import (
	"encoding/json"
	"fmt"
	"time"

	"github.com/nats-io/nats.go"
)

type OrderPlaced struct {
	ID    string `json:"id"`
	Total int64  `json:"total"`
}

func main() {
	nc, err := nats.Connect(nats.DefaultURL)
	if err != nil {
		panic(err)
	}
	defer nc.Drain()

	// Consumer: another service reacts to the event on its own schedule.
	_, _ = nc.Subscribe("orders.placed", func(m *nats.Msg) {
		var e OrderPlaced
		if err := json.Unmarshal(m.Data, &e); err != nil {
			return
		}
		fmt.Printf("inventory: reserving stock for order %s ($%d)\n", e.ID, e.Total)
	})

	// Producer: fire-and-forget, does not block on consumers.
	data, _ := json.Marshal(OrderPlaced{ID: "o-42", Total: 1999})
	if err := nc.Publish("orders.placed", data); err != nil {
		panic(err)
	}

	time.Sleep(100 * time.Millisecond) // let the async consumer run
}

package main

import (
	"fmt"
	"sync"
)

// processedStore records which message IDs we've already handled.
type processedStore struct {
	mu   sync.Mutex
	seen map[string]bool // in prod: Redis/DB with a UNIQUE constraint
}

// Handle applies the side effect at most once per message ID.
func (p *processedStore) Handle(msgID string, apply func()) {
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.seen[msgID] {
		fmt.Printf("skip duplicate %s\n", msgID) // safe retry
		return
	}
	apply()               // charge card, send email, etc.
	p.seen[msgID] = true  // mark processed AFTER success
}

func main() {
	p := &processedStore{seen: map[string]bool{}}
	charge := func() { fmt.Println("charged $19.99") }

	// Broker redelivers the same message ID three times.
	for i := 0; i < 3; i++ {
		p.Handle("pay-42", charge)
	}
}

