package solution

import (
	"context"
	"time"
)

// CallWithBudget bounds a single hop to perHop, but never past the parent's deadline.
func CallWithBudget(parent context.Context, perHop time.Duration, call func(context.Context) error) error {
	// WithTimeout already clamps to the parent's deadline if the parent's is sooner,
	// because the child inherits the parent and fires on whichever deadline hits first.
	ctx, cancel := context.WithTimeout(parent, perHop)
	defer cancel() // always release the timer / cancel goroutine
	return call(ctx)
}

