func TestClampsToPerHop(t *testing.T) {
	err := CallWithBudget(context.Background(), 30*time.Millisecond, func(ctx context.Context) error {
		<-ctx.Done()
		return ctx.Err()
	})
	if err != context.DeadlineExceeded {
		t.Fatalf("want DeadlineExceeded, got %v", err)
	}
}

func TestClampsToParent(t *testing.T) {
	parent, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	start := time.Now()
	_ = CallWithBudget(parent, 500*time.Millisecond, func(ctx context.Context) error {
		<-ctx.Done()
		return ctx.Err()
	})
	if elapsed := time.Since(start); elapsed > 200*time.Millisecond {
		t.Fatalf("child outlived parent: %v", elapsed)
	}
}

