package solution

import "sync"

type Deduper struct {
	mu   sync.Mutex
	seen map[string]bool
}

func NewDeduper() *Deduper {
	return &Deduper{seen: map[string]bool{}}
}

// Process runs apply at most once per id; failed applies may be retried.
func (d *Deduper) Process(id string, apply func() error) error {
	d.mu.Lock()
	if d.seen[id] {
		d.mu.Unlock()
		return nil // already done: safe no-op on redelivery
	}
	d.mu.Unlock()

	if err := apply(); err != nil {
		return err // do NOT mark processed, so a retry can re-apply
	}

	d.mu.Lock()
	d.seen[id] = true // mark only after success
	d.mu.Unlock()
	return nil
}

