package solution

import (
	"errors"
	"testing"
)

func TestAtMostOnce(t *testing.T) {
	d := NewDeduper()
	calls := 0
	apply := func() error { calls++; return nil }
	for i := 0; i < 3; i++ {
		if err := d.Process("m1", apply); err != nil {
			t.Fatal(err)
		}
	}
	if calls != 1 {
		t.Fatalf("want 1 apply, got %d", calls)
	}
}

func TestFailureRetryable(t *testing.T) {
	d := NewDeduper()
	calls := 0
	flaky := func() error {
		calls++
		if calls == 1 {
			return errors.New("transient")
		}
		return nil
	}
	if err := d.Process("m2", flaky); err == nil {
		t.Fatal("want error on first try")
	}
	if err := d.Process("m2", flaky); err != nil {
		t.Fatal(err)
	}
	if calls != 2 {
		t.Fatalf("want 2 applies (1 fail + 1 success), got %d", calls)
	}
}

