func (h *Handler) Checkout(w http.ResponseWriter, r *http.Request) {
	// Inherit the client's context AND cap this hop at 200ms.
	ctx, cancel := context.WithTimeout(r.Context(), 200*time.Millisecond)
	defer cancel()

	price, err := h.pricing.Quote(ctx, r.FormValue("sku")) // fails fast on slowness
	if err != nil {
		if errors.Is(err, context.DeadlineExceeded) {
			http.Error(w, "pricing timed out", http.StatusGatewayTimeout) // 504
			return
		}
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	fmt.Fprintf(w, "price: %d", price)
}

func CallWithRetry(ctx context.Context, maxAttempts int, call func(context.Context) error) error {
	const base = 20 * time.Millisecond
	var lastErr error
	for attempt := 0; attempt < maxAttempts; attempt++ {
		if err := ctx.Err(); err != nil {
			return err // caller already cancelled/timed out
		}
		lastErr = call(ctx)
		if lastErr == nil {
			return nil // success
		}
		if attempt == maxAttempts-1 {
			break // no sleep after the final attempt
		}
		// Exponential backoff with jitter.
		backoff := base * time.Duration(1<<attempt)
		jitter := time.Duration(rand.Int63n(int64(backoff) + 1))
		select {
		case <-ctx.Done():
			return ctx.Err() // cancellation beats the sleep
		case <-time.After(backoff + jitter):
		}
	}
	return lastErr
}
